import { AIChatRoot } from "@/components/bevelui/ai-chat";

export default function ChatPage() {
  return (
    <div className="h-screen flex flex-col">
      <AIChatRoot
        config={{
          assistantName:  "Aria",
          welcomeTitle:   "What can I help with?",
          starters: [
            "Explain React Server Components",
            "Write a debounce hook",
          ],
          models: [
            { value: "claude-sonnet", label: "Claude Sonnet" },
            { value: "gpt-4o",        label: "GPT-4o"        },
          ],
        }}
        onSend={async (text, { appendToken, setStatus, signal }) => {
          const res = await fetch("/api/chat", {
            method: "POST",
            body:   JSON.stringify({ message: text }),
            signal,
          });

          const reader  = res.body!.getReader();
          const decoder = new TextDecoder();

          while (true) {
            const { done, value } = await reader.read();
            if (done) break;
            appendToken(decoder.decode(value));
          }

          setStatus("done");
        }}
      />
    </div>
  );
}

import { useChat } from "ai/react";
import { AIChatRoot } from "@/components/bevelui/ai-chat";

export function VercelChat() {
  const { messages, append, isLoading, stop } = useChat();

  // Map Vercel AI SDK messages to AIMessage format
  const mapped = messages.map(m => ({
    id:      m.id,
    role:    m.role as "user" | "assistant",
    status:  (isLoading && m === messages[messages.length - 1] ? "streaming" : "done") as any,
    content: [{ type: "text" as const, text: m.content }],
  }));

  return (
    <AIChatRoot
      messages={mapped}
      isLoading={isLoading}
      onSendControlled={(text) => append({ role: "user", content: text })}
      onStop={stop}
    />
  );
}

// All block types
type AIContentBlock =
  | { type: "text";      text: string }                                    // GFM markdown
  | { type: "thinking";  text: string; collapsed?: boolean }              // collapsible reasoning
  | { type: "tool-call"; name: string; status: "pending"|"running"|"done"|"error"; result?: string }
  | { type: "code";      code: string; language: string; filename?: string }
  | { type: "image";     url: string;  alt?: string }
  | { type: "file";      name: string; mimeType: string; size?: number };

onSend={async (text, { appendThinkingToken, appendToken, setStatus, signal }) => {
  const res = await fetch("/api/chat", { method: "POST", body: JSON.stringify({ text }), signal });

  for await (const chunk of res.body!) {
    const { type, delta } = JSON.parse(chunk);

    if (type === "thinking_delta") appendThinkingToken(delta); // → thinking block
    if (type === "text_delta")     appendToken(delta);          // → text block
  }

  setStatus("done");
}}

onSend={async (text, { addBlock, updateBlock, appendToken, setStatus }) => {
  // Model decides to search the web
  addBlock({
    type:   "tool-call",
    id:     "search-1",
    name:   "web_search",
    label:  "Searching the web...",
    status: "running",
  });

  const results = await webSearch(text);

  // block index 0 = tool-call (first block added)
  updateBlock(0, { status: "done", result: results.summary });

  // Now stream the response
  for (const token of results.answer) appendToken(token);
  setStatus("done");
}}

onSend={async (text, { appendToken, setStatus, signal }) => {
  // Pass signal to fetch — aborts cleanly when Stop is clicked
  const res = await fetch("/api/stream", { signal });

  try {
    for await (const chunk of streamResponse(res)) {
      appendToken(chunk);
    }
    setStatus("done");
  } catch (e) {
    // AbortError is caught by AIChatRoot automatically
    // — no need to handle it here
    throw e;
  }
}}
